def solve(n):
    k = max(1, int(math.isqrt(n)))
    eps = 2e-9
    s = min(1.0, 1.0 / k + eps)
    out = []
    for i in range(k):
        for j in range(k):
            if len(out) < n:
                out.append((min(1.0, (i + 0.5) / k), min(1.0, (j + 0.5) / k), 0.0, s))
    while len(out) < n:
        out.append((0.0, 0.0, 0.0, 0.0))
    return out

