def _search(C, N, tl):
    divs = [[] for _ in range(N + 1)]
    for d in range(1, N + 1):
        for m in range(d, N + 1, d):
            divs[m].append(d)
    x = [0] * (N + 2); S = [0] * (N + 2); tried = [0] * (N + 2)
    n = 1; best = []; t = time.time(); it = 0
    while 1 <= n <= N:
        it += 1
        if it % 2000 == 0 and time.time() - t > tl:
            break
        placed = False
        while tried[n] < 2:
            v = 1 if tried[n] == 0 else -1
            tried[n] += 1
            if all(abs(S[d] + v) <= C for d in divs[n]):
                x[n] = v
                for d in divs[n]:
                    S[d] += v
                placed = True
                break
        if placed:
            if n > len(best):
                best = x[1:n + 1]
            n += 1
            if n <= N:
                tried[n] = 0
        else:
            n -= 1
            if n >= 1:
                v = x[n]
                for d in divs[n]:
                    S[d] -= v
    return best

