def solve():
    import itertools
    import math
    import numpy as np

    def build(d, n):
        b = 2 * n + 1
        pts = []
        for x in itertools.product(range(n + 1), repeat=d):
            if sum(x) <= n:
                v = 0
                for c in x:
                    v = v * b + c
                pts.append(v)
        return pts

    best, best_score = [0, 1], -1.0
    for d, n in [(4, 14), (5, 10), (6, 8), (7, 7), (8, 5), (9, 4)]:
        pts = build(d, n)
        if len(pts) > 4000 or len(pts) < 2:
            continue
        a = np.array(pts, dtype=np.int64)
        s = np.unique((a[:, None] + a[None, :]).ravel()).size
        df = np.unique((a[:, None] - a[None, :]).ravel()).size
        sc = math.log(df) / math.log(s) + (1 - 1.0 / len(pts)) / 100
        if sc > best_score:
            best_score, best = sc, pts
    return [int(v) for v in best]

